import manifest from './photos.manifest.json'
import type { CategorySlug } from './categories'

/**
 * Editorial metadata for each photograph. The technical data (size, blur
 * placeholder, camera settings) is generated by `npm run images` into
 * photos.manifest.json — this file only holds what a human writes.
 *
 * To add a photo: drop it into ../portfolio/<Category>/, run `npm run images`,
 * then add an entry here keyed by its id (printed in the manifest).
 * Photos without an entry still appear, with a generic alt text.
 */
interface PhotoMeta {
  title: string
  alt: string
  /** Show on the homepage "Selected work" grid (in this order). */
  featured?: number
  /** CSS object-position for crops, e.g. '50% 30%'. */
  focus?: string
}

