export interface Exif {
  camera?: string
  lens?: string
  focal?: string
  aperture?: string
  shutter?: string
  iso?: string
}

export interface Photo {
  id: string
  category: CategorySlug
  title: string
  alt: string
  /** Path without width suffix, e.g. /photos/nature/img-1991 */
  path: string
  width: number
  height: number
  blur: string
  color: string
  exif?: Exif
  featured?: number
  focus?: string
}

export const photos: Photo[] = (manifest as Array<Omit<Photo, 'title' | 'alt'>>).map((p) => ({
  ...p,
  title: meta[p.id]?.title ?? 'Untitled',
  alt: meta[p.id]?.alt ?? `Photograph from the ${p.category} series by Martin Gidikovv.`,
  featured: meta[p.id]?.featured,
  focus: meta[p.id]?.focus,
}))

export const photoById = new Map(photos.map((p) => [p.id, p]))
export const getPhoto = (id: string) => {
  const p = photoById.get(id)
  if (!p) throw new Error(`Unknown photo id: ${id}`)
  return p
}

export const featuredPhotos = photos
  .filter((p) => p.featured)
  .sort((a, b) => (a.featured ?? 0) - (b.featured ?? 0))

export const photosIn = (category?: CategorySlug) =>
  category ? photos.filter((p) => p.category === category) : photos

/** Interleave categories so "All" reads as a varied sequence, not five blocks. */
export const allPhotosCurated = (() => {
  const buckets = new Map<string, Photo[]>()
  for (const p of photos) buckets.set(p.category, [...(buckets.get(p.category) ?? []), p])
  const lists = [...buckets.values()]
  const out: Photo[] = []
  for (let i = 0; out.length < photos.length; i++) for (const l of lists) if (l[i]) out.push(l[i])
  return out
})()
